/* Original levels, generated by reverse pulls then verified by a forward solver. */
const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const {sokoParse,sokoNeighbour,sokoFloor,sokoStep,sokoWon,sokoReach,sokoSolve}=require('./sokoban-core.js');
let seed=27182818;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
const pick=items=>items[Math.floor(random()*items.length)];
const levels=[],seen=new Set();
const groups=[['First steps',6,6,1,1,6],['Plan ahead',7,7,2,4,10],['Think in boxes',8,7,3,6,14],['Warehouse craft',9,8,4,9,18]];
for(let group=0;group<groups.length;group++){
  const [pack,width,height,count,minimum,maximum]=groups[group];let tries=0,found=[];
  while(found.length<10){
    if(++tries>2000)throw Error('Level generation quota failed '+pack);
    const rows=Array.from({length:height},(_,y)=>Array.from({length:width},(_,x)=>x===0||y===0||x===width-1||y===height-1?'#':' '));
    // A few interior pillars make each room distinct without importing a level set.
    for(let p=0;p<group+1;p++)if(random()<0.8)rows[2+Math.floor(random()*(height-4))][2+Math.floor(random()*(width-4))]='#';
    const free=[];for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++)if(rows[y][x]===' ')free.push(y*width+x);
    const goals=[];while(goals.length<count){const cell=pick(free);if(!goals.includes(cell))goals.push(cell);}
    for(const cell of goals)rows[Math.floor(cell/width)][cell%width]='.';
    const player=pick(free.filter(p=>!goals.includes(p)));rows[Math.floor(player/width)][player%width]='@';
    for(const cell of goals)rows[Math.floor(cell/width)][cell%width]='*';
    const board=sokoParse(rows.map(r=>r.join('')));let state=board.start;
    for(let step=0;step<8+group*8;step++){
      const reach=sokoReach(board,state),possible=[];
      for(const position of reach.keys())for(const direction of 'UDLR'){
        const box=sokoNeighbour(board,position,direction),away=sokoNeighbour(board,position,{U:'D',D:'U',L:'R',R:'L'}[direction]);
        if(state.boxes.includes(box)&&sokoFloor(board,away)&&!state.boxes.includes(away))possible.push({position,box,away});
      }
      if(!possible.length)break;
      const p=pick(possible);state={player:p.away,boxes:state.boxes.map(b=>b===p.box?p.position:b).sort((a,b)=>a-b),pushes:0};
    }
    if(sokoWon(board,state))continue;
    for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=y*width+x;if(rows[y][x]!=='#')rows[y][x]=board.goals.has(i)?'.':' ';}
    for(const cell of state.boxes)rows[Math.floor(cell/width)][cell%width]=board.goals.has(cell)?'*':'$';
    rows[Math.floor(state.player/width)][state.player%width]=board.goals.has(state.player)?'+':'@';
    const map=rows.map(r=>r.join('')),signature=map.join('\n');if(seen.has(signature))continue;
    const verify=sokoParse(map),result=sokoSolve(verify,verify.start,{maxStates:30000,maxMs:400});
    if(result.status!=='solved'||result.pushes<minimum||result.pushes>maximum)continue;
    let replay=verify.start;for(const d of result.path){replay=sokoStep(verify,replay,d);assert(replay);}assert(sokoWon(verify,replay));
    found.push({map,solution:result.path,minimumPushes:result.pushes});seen.add(signature);
  }
  found.sort((a,b)=>a.minimumPushes-b.minimumPushes||a.solution.length-b.solution.length);
  if(group===0)found[0]={map:['#######','#     #','# @$ .#','#     #','#######'],solution:'RR',minimumPushes:2};
  const names=[['First delivery','Find the angle','One careful turn','Around the corner','The long way','Room to move','A quiet detour','Line it up','Step behind','Ready for more'],['Two destinations','Give yourself space','Crossing paths','Open the lane','One at a time','Leave an exit','Side by side','Make a passage','The right order','Double delivery'],['Three little plans','Beyond the pillar','A spare square','The narrow turn','Keep it open','Middle ground','Change the angle','Boxes in balance','A patient route','Three in place'],['Four destinations','The loading bay','Clear the entrance','A turn ahead','Between the aisles','Room for four','The careful shuffle','A winding route','Final deliveries','Warehouse master']][group];
  found.forEach((level,i)=>levels.push({id:'sk-'+String(levels.length+1).padStart(3,'0'),pack,title:names[i],...level}));
  console.log(pack+': 10 solvable levels verified; minimum pushes '+found.map(p=>p.minimumPushes).join(', '));
}
const target=path.resolve(__dirname,'../data/sokoban/levels.json');fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,JSON.stringify({source:'Original Study Hub levels',levels}));
